def int_to_roman(n):
    vals = [(1000, "M"), (500, "D"), (100, "C"), (50, "L"),
            (10, "X"), (5, "V"), (1, "I")]
    out = ""
    for v, sym in vals:
        while n >= v:
            out += sym
            n -= v
    return out

